    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // Provide the test contract with enough Ether to fund c if needed.
        require(address(this).balance >= amount);

        // Credit this test contract inside c so withdrawBalance has something to withdraw.
        c.addToBalance{value: amount}();

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the caller's stored balance is zero after withdrawBalance finishes,
        // whether the call succeeded or reverted. (A revert happens here only if the transfer fails.)
        assert(c.getBalance(address(this)) == 0);
    }

    receive() external payable {}
}

